src='''def transform(grid):
    """Recolor the six 4x4 motifs by their containment in the densest motif."""
    out = [row[:] for row in grid]
    origins = [(1, 1), (1, 6), (6, 1), (6, 6), (11, 1), (11, 6)]
    patches = [[tuple(grid[r + dr][c + dc] for dc in range(4)) for dr in range(4)]
               for r, c in origins]
    counts = [sum(v == 2 for row in p for v in row) for p in patches]
    # The most detailed motif is the reference and is colored 3.
    ref_i = max(range(6), key=lambda i: counts[i])
    ref = patches[ref_i]
    seen = set()
    for i, ((r, c), patch) in enumerate(zip(origins, patches)):
        if i == ref_i:
            color = 3
        else:
            signature = tuple(v for row in patch for v in row)
            contained = all(patch[dr][dc] != 2 or ref[dr][dc] == 2
                            for dr in range(4) for dc in range(4))
            if contained and signature not in seen:
                color = 8
                seen.add(signature)
            else:
                color = 2
        for dr in range(4):
            for dc in range(4):
                if grid[r + dr][c + dc] == 2:
                    out[r + dr][c + dc] = color
    return out
'''
